INSERT INTO scenarios (id,name,description,locations,participant_min,participant_max,scene_phases,event_pool,available_actions,heat_modifier,roleplay_compatibility) VALUES
('0d0bda7e-0001-4db0-8c00-000000000001','Blind Date','Meet a fictional adult whose deeper personality is discovered through observation, timing, and reactions.','["Cafe","Rooftop Restaurant","Cocktail Lounge","Beach Bar","Hotel Lounge","Night Club","Private Dinner","Resort","Penthouse Bar"]',1,1,'["arrival","first_meeting","chemistry","decision"]','["late_arrival","shared_laugh","guarded_pause","unexpected_confidence"]','["observe","eye_contact","smile","approach","tease","flirt","compliment","change_topic","move_closer","order_drink","change_location","invite_continue","step_back","end_date"]',4,'["Mysterious Stranger","Confident Stranger","Secret Crush"]'),
('0d0bda7e-0002-4db0-8c00-000000000002','Midnight Circle','Three fictional adults reconnect at a rooftop party; alliances and attention shift naturally.','["Rooftop","Lounge","Balcony","Private Bar"]',2,5,'["arrival","group_spark","friction","after_hours"]','["alliance","jealous_glance","private_chat","music_shift"]','["observe","join","flirt","tease","focus_character","shift_attention","let_them_talk","director_card"]',2,'["VIP","Rival","Host","Unexpected Guest"]'),
('0d0bda7e-0003-4db0-8c00-000000000003','Masquerade Signals','A playful mystery at a masked rooftop event. Roles add texture without replacing personality.','["Grand Hall","Terrace","Moonlit Bar"]',1,5,'["masks_on","first_clue","reveal","choice"]','["secret_message","role_reversal","masked_dance"]','["observe","approach","flirt","tease","change_topic","start_roleplay","director_card"]',3,'["Spy","Detective","Suspect","Royal"]'),
('0d0bda7e-0004-4db0-8c00-000000000004','After Dark Lounge','A high-chemistry late lounge scene where consent and emotional clarity set every pace.','["Cocktail Lounge","Terrace","Private Lounge"]',1,3,'["warmup","chemistry","private_offer","aftermath"]','["intense_eye_contact","quiet_check_in","private_invitation"]','["observe","flirt","compliment","move_closer","invite_continue","slow_down","stop_scene"]',8,'["VIP","Mysterious Stranger","Old Flame"]')
