('e1d10000-0007-4db0-8c00-000000000007','Beach House','A relaxed social scene that can become emotionally complicated.','["Deck","Kitchen","Beach","Garden"]',2,5,'["arrival","shared_activity","night"]','["shared_laugh","jealous_glance","private_chat"]','["join","tease","let_them_talk","director_card"]',2,'["Rival","Old Flame"]'),
