('e1d10000-0009-4db0-8c00-000000000009','Club Afterparty','High energy with clear boundaries and multiple social currents.','["Dance Floor","Lounge","Terrace"]',2,5,'["arrival","energy","wind_down"]','["attention_shift","quiet_check_in","private_invitation"]','["flirt","shift_attention","step_back","director_card"]',6,'["Celebrity","VIP","Spy"]'),
('e1d10000-0010-4db0-8c00-000000000010','Weekend Getaway','A longer story with changing locations and consequences.','["Cabin","Garden","Private Dinner","Terrace"]',1,5,'["arrival","night","next_morning","next_day"]','["shared_memory","late_talk","morning_aftermath"]','["continue_night","next_morning","next_day","change_location"]',2,'["Old Flame","Secret Crush","Vacation Stranger"]'),
('e1d10000-0011-4db0-8c00-000000000011','Mysterious Strangers','A roleplay-focused night of observation and carefully earned reveals.','["Lounge","Balcony","Private Bar"]',1,5,'["cover","clue","reveal"]','["secret_message","false_lead","role_reversal"]','["observe","start_roleplay","director_card"]',3,'["Mysterious Stranger","Spy","Double Agent"]'),
