INSERT INTO scenario_roles (name,description) VALUES
('Mysterious Stranger','Keeps details just out of reach.'),('Confident Stranger','Makes a clear first impression.'),('Celebrity','Draws attention without owning the room.'),('VIP','Moves through the scene with poise.'),('Bodyguard','Notices every change in the room.'),('Rival','Creates a lively challenge.'),('Royal','Carries a theatrical sense of occasion.'),('Mysterious Guest','Arrives with an unanswered question.'),('Spy','Performs confidence while holding a secret.'),('Double Agent','Changes loyalties as the story develops.'),('Detective','Follows social clues.'),('Suspect','Has a story to protect.'),('Vampire','Adds gothic theatricality.'),('Hunter','Brings focused resolve.'),('Host','Shapes the night without controlling people.'),('Unexpected Guest','Shifts the social balance.'),('Vacation Stranger','Makes a fleeting night feel significant.'),('Performer','Uses charm as a stage presence.'),('Backstage Guest','Knows the hidden side of the event.'),('Neighbour','Makes the familiar suddenly charged.'),('Roommate','Knows everyday details.'),('Secret Crush','Hides feeling in plain sight.'),('Old Flame','Carries a shared history.')
