SELECT 'line_' || n, style, text, tags::jsonb FROM (VALUES
(1,'shy','Their smile arrives a second late, but it is genuine.','["shy","flirt"]'),(2,'shy','They glance away, then meet your eyes again.','["shy","eye_contact"]'),(3,'confident','They lean in just enough to make the moment feel intentional.','["confident","flirt"]'),(4,'confident','"I was hoping you would come over," they say.','["confident","approach"]'),(5,'mysterious','"Maybe you will earn the rest of that story," they say.','["mysterious","discovery"]'),(6,'mysterious','A half-smile leaves the meaning open.','["mysterious","reaction"]'),(7,'teasing','"Careful. That sounded almost charming," they say.','["teasing","flirt"]'),(8,'teasing','They raise an eyebrow as if inviting a better answer.','["teasing","reaction"]'),(9,'romantic','The music seems to soften around the conversation.','["romantic","mood"]'),(10,'romantic','"I like that you noticed," they say quietly.','["romantic","compliment"]'),
(11,'intense','Their focus settles on you, steady and unhurried.','["intense","attention"]'),(12,'intense','The pause carries more feeling than the words.','["intense","tension"]'),(13,'playful','They laugh, then make room beside them.','["playful","invite"]'),(14,'playful','"That was a daring choice," they grin.','["playful","tease"]'),(15,'reserved','They take a moment before answering.','["reserved","trust"]'),(16,'reserved','"I appreciate you not rushing me," they say.','["reserved","consent"]'),(17,'curious','"What made you choose this place?" they ask.','["curious","scene"]'),(18,'curious','They notice the detail you thought nobody saw.','["curious","observation"]'),(19,'jealous','Their attention flickers to the other conversation.','["jealous","group"]'),(20,'jealous','"You seem popular tonight," they say, trying to sound casual.','["jealous","reaction"]'),
(21,'protective','"You okay with the noise here?" they ask.','["protective","comfort"]'),(22,'protective','They create a little room for you in the crowd.','["protective","action"]'),(23,'competitive','"That is your opening move? Interesting," they say.','["competitive","tease"]'),(24,'competitive','They turn the challenge into a playful spark.','["competitive","flirt"]'),(25,'social','They wave someone over, then keep you included.','["social","group"]'),(26,'social','The room seems brighter around their laugh.','["social","mood"]'),(27,'private','"Could we find somewhere quieter?" they ask.','["private","private_offer"]'),(28,'private','They prefer the conversation away from the crowd.','["private","location"]'),(29,'guarded','"That is a question for later," they say with a small smile.','["guarded","discovery"]'),(30,'expressive','Their face gives away their delight.','["expressive","reaction"]'),
(31,'calm','They slow the conversation into something easy.','["calm","recovery"]'),(32,'unpredictable','They change the subject with a surprising observation.','["unpredictable","scene"]'),(33,'bold','"Come on. Let us see where this goes," they say.','["bold","invite"]'),(34,'patient','"There is no rush," they say.','["patient","consent"]'),(35,'observant','They catch your hesitation and wait.','["observant","consent"]'),(36,'slow_burn','The connection grows in the spaces between lines.','["slow_burn","chemistry"]'),(37,'flirty','They hold eye contact a beat longer.','["flirty","eye_contact"]'),(38,'adventurous','"A different view might change the night," they say.','["adventurous","location"]'),(39,'independent','"I am here because I chose to be," they say.','["independent","confidence"]'),(40,'impulsive','They follow a sudden thought, then check your reaction.','["impulsive","reaction"]'),
(41,'roleplay','The role slips for a second, revealing the person underneath.','["roleplay","discovery"]'),(42,'roleplay','"My cover is convincing, right?" they tease.','["roleplay","tease"]'),(43,'group','Someone notices the look that passes between you.','["group","group"]'),(44,'group','Two conversations collide, changing the room.','["group","event"]'),(45,'recovery','They appreciate the change of topic.','["recovery","comfort"]'),(46,'recovery','The moment resets without losing its warmth.','["recovery","mood"]'),(47,'private_offer','"We could keep talking somewhere quieter—only if you want to," they say.','["private_offer","consent"]'),(48,'private_offer','The invitation is there, but there is no pressure behind it.','["private_offer","consent"]'),(49,'aftermath','The next silence feels different: warmer, more familiar.','["aftermath","relationship"]'),(50,'aftermath','Something new is understood, even if nobody names it yet.','["aftermath","discovery"]')
